300:   if (flags) {
301:     query.flags = flags
302:   }
303: 
304:   var yamlToken
305:   try {
306:     var loadedYamlFile = jsYaml.safeLoad(fs.readFileSync(query.yaml, 'utf8'))
307:     yamlToken =
308:       loadedYamlFile && loadedYamlFile.codecov && loadedYamlFile.codecov.token
309:   } catch (e) {
310:     // silently fail
311:   }
312:   var token =
313:     args.options.token ||
314:     yamlToken ||
315:     process.env.codecov_token ||
316:     process.env.CODECOV_TOKEN
317:   if (token) {
318:     query.token = token
319:   }
