328:     branch: query.branch,
329:     package: query.package,
330:   })
331: 
332:   var upload = ''
333: 
334:   // Add specified env vars
335:   var env_found = false
336:   if (args.options.env || process.env.CODECOV_ENV || process.env.codecov_env) {
337:     var env = (
338:       args.options.env +
339:       ',' +
340:       (process.env.CODECOV_ENV || '') +
341:       ',' +
342:       (process.env.codecov_env || '')
343:     ).split(',')
344:     for (var i = env.length - 1; i >= 0; i--) {
345:       if (env[i]) {
346:         upload += env[i] + '=' + (process.env[env[i]] || '').toString() + '\n'
347:         env_found = true
348:       }
349:     }
350:     if (env_found) {
351:       upload += '<<<<<< ENV\n'
352:     }
353:   }
354: 
355:   // List git files
356:   var root = path.resolve(args.options.root || query.root || '.')
357:   console.log('==> Building file structure')
358:   try {
359:     upload +=
360:       execSync('git ls-files || hg locate', { cwd: root })
361:         .toString()
362:         .trim() + '\n<<<<<< network\n'
363:   } catch (err) {
364:     // not a git/hg dir, emulating git/hg ignore behavior
365:     upload +=
366:       walk
367:         .sync({ path: root, ignoreFiles: ['.gitignore', '.hgignore'] })
368:         .join('\n')
369:         .trim() + '\n<<<<<< network\n'
370:   }
371:   // Make gcov reports
372:   if ((args.options.disable || '').split(',').indexOf('gcov') === -1) {
373:     try {
374:       console.log('==> Generating gcov reports (skip via --disable=gcov)')
375:       var gcg = args.options['gcov-glob'] || ''
376:       if (gcg) {
377:         if (!isWindows) {
378:           gcg = gcg
379:             .split(' ')
380:             .map(function(p) {
381:               return "-not -path '" + p + "'"
382:             })
383:             .join(' ')
384:         } else {
385:           gcg = gcg
386:             .split(' ')
387:             .map(function(p) {
388:               return '^| findstr /i /v ' + p
389:             })
390:             .join(' ')
391:         }
392:       }
393:       var gcov
394:       if (!isWindows) {
395:         gcov =
396:           'find ' +
397:           (args.options['gcov-root'] || root) +
398:           " -type f -name '*.gcno' " +
399:           gcg +
400:           ' -exec ' +
401:           (validator.escape(args.options['gcov-exec']) || 'gcov') +
402:           ' ' +
403:           (validator.escape(args.options['gcov-args']) || '') +
404:           ' {} +'
405:       } else {
406:         // @TODO support for root
407:         // not straight forward due to nature of windows command dir
408:         gcov =
409:           'for /f "delims=" %g in (\'dir /a-d /b /s *.gcno ' +
410:           gcg +
411:           "') do " +
412:           (args.options['gcov-exec'] || 'gcov') +
413:           ' ' +
414:           (args.options['gcov-args'] || '') +
415:           ' %g'
416:       }
417:       debug.push(gcov)
418:       console.log('    $ ' + gcov)
419:       execSync(gcov)
420:     } catch (e) {
421:       console.log('    Failed to run gcov command.')
422:     }
423:   } else {
424:     debug.push('disabled gcov')
425:   }
426: 
427:   // Detect .bowerrc
428:   var bowerrc
429:   if (!isWindows) {
430:     bowerrc = execSync('test -f .bowerrc && cat .bowerrc || echo ""', {
431:       cwd: root,
432:     })
433:       .toString()
434:       .trim()
435:   } else {
436:     bowerrc = execSync('if exist .bowerrc type .bowerrc', { cwd: root })
437:       .toString()
438:       .trim()
439:   }
440:   if (bowerrc) {
441:     bowerrc = JSON.parse(bowerrc).directory
442:     if (bowerrc) {
443:       if (!isWindows) {
444:         more_patterns =
445:           " -not -path '*/" + bowerrc.toString().replace(/\/$/, '') + "/*'"
446:       } else {
447:         more_patterns =
448:           '| findstr /i /v \\' + bowerrc.toString().replace(/\/$/, '') + '\\'
449:       }
450:     }
451:   }
452: 
453:   var files = [],
454:     file = null
455:   if (args.options.pipe) {
456:     // Append piped reports
457:     upload += '# path=piped\n' + args.options.pipe.join('') + '\n<<<<<< EOF\n'
458:     console.log('==> Reading report from stdin')
459:   } else if (args.options.file) {
460:     // Append manually entered reports
461:     file = args.options.file
462:     console.log('==> Targeting specific file')
463:     try {
464:       upload +=
465:         '# path=' +
466:         file +
467:         '\n' +
468:         fs.readFileSync(file, 'utf8').toString() +
469:         '\n<<<<<< EOF\n'
470:       console.log('    + ' + file)
471:       files.push(file)
472:     } catch (e) {
473:       debug.push('failed: ' + file.split('/').pop())
474:       console.log('    X Failed to read file at ' + file)
475:     }
476:   } else if ((args.options.disable || '').split(',').indexOf('search') === -1) {
477:     console.log('==> Scanning for reports')
478:     var _files
479:     if (!isWindows) {
480:       _files = execSync('find ' + root + ' ' + patterns + more_patterns)
481:         .toString()
482:         .trim()
483:         .split('\n')
484:     } else {
485:       // @TODO support for a root directory
486:       // It's not straightforward due to the nature of the dir command
487:       _files = execSync('dir ' + patterns + more_patterns)
488:         .toString()
489:         .trim()
490:         .split('\r\n')
491:     }
492:     if (_files) {
493:       for (var i2 = _files.length - 1; i2 >= 0; i2--) {
494:         file = _files[i2]
495:         try {
496:           upload +=
497:             '# path=' +
498:             file +
499:             '\n' +
500:             fs.readFileSync(file, 'utf8').toString() +
501:             '\n<<<<<< EOF\n'
502:           console.log('    + ' + file)
503:           files.push(file)
504:         } catch (e) {
505:           debug.push('failed: ' + file.split('/').pop())
506:           console.log('    X Failed to read file at ' + file)
507:         }
508:       }
509:     }
510:   } else {
511:     debug.push('disabled search')
512:   }
513: 
514:   if (files) {
515:     // Upload to Codecov
516:     if (args.options.dump) {
517:       console.log('-------- DEBUG START --------')
518:       console.log(upload)
519:       console.log('-------- DEBUG END --------')
520:     } else {
521:       console.log('==> Uploading reports')
522:       var _upload
523:       if ((args.options.disable || '').split(',').indexOf('s3') === -1) {
524:         _upload = sendToCodecovV3
525:       } else {
526:         _upload = sendToCodecovV2
527:       }
528:       _upload(
529:         codecov_endpoint,
530:         query,
531:         upload,
532:         function() {
533:           // remove files after Uploading
534:           if (args.options.clear) {
535:             for (var i = files.length - 1; i >= 0; i--) {
536:               try {
537:                 fs.unlinkSync(files[i])
538:               } catch (e) {}
539:             }
540:           }
541:           if (on_success) {
542:             on_success.apply(this, arguments)
543:           }
544:         },
545:         on_failure || function() {}
546:       )
547:     }
548:   }
549: 
